(()=>{
 const panel=document.createElement('details');panel.id='dynamics-panel';panel.className='advanced';const summary=document.createElement('summary');summary.textContent='Forces, collisions & lifetime';panel.append(summary);
 function note(text){const p=document.createElement('p');p.className='animation-intro';p.textContent=text;panel.append(p);}
 note('Combine forces for tornadoes, drifting smoke, attraction fields, and debris. Locked ring movement ignores forces and collisions.');
 for(const [title,keys] of [['Wind & resistance',['windX','windY','windZ','drag']],['Attraction & swirl',['attraction','vortexForce','vortexLift','forceX','forceY','forceZ']],['Spin & lifetime',['rotationSpeed']],['Collision surface',['collisionHeight','restitution','surfaceFriction']]]){const heading=document.createElement('h3');heading.textContent=title;panel.append(heading);for(const key of keys){const [name,min,max,value]=EmberDynamics.ranges[key],label=document.createElement('label'),input=document.createElement('input');label.textContent=name;input.id='dynamics-'+key;input.type='number';input.min=min;input.max=max;input.step='any';input.value=value;input.setAttribute('aria-label',name);input.oninput=()=>{if(!input.checkValidity()||!Number.isFinite(input.valueAsNumber))return;state[key]=input.valueAsNumber;persist();};label.append(input);panel.append(label);}}
 const response=document.createElement('label');response.textContent='On collision';const select=document.createElement('select');select.id='dynamics-collisionResponse';select.setAttribute('aria-label','On collision');select.innerHTML='<option value="bounce">Bounce</option><option value="kill">Remove particle</option>';select.onchange=()=>{state.collisionResponse=select.value;sync();persist();};response.append(select);panel.append(response);
 note('Enable “Collide with a surface” above to activate this surface. Its height is measured in effect-local centimeters. This is a flat surface, not Unreal scene geometry.');
 const life=document.createElement('label');life.className='switch-label';life.textContent='Color over lifetime';const toggle=document.createElement('input');toggle.id='dynamics-colorOverLife';toggle.type='checkbox';toggle.oninput=()=>{state.colorOverLife=toggle.checked;sync();persist();};life.append(toggle);panel.append(life);const end=document.createElement('label');end.textContent='Fade toward';const color=document.createElement('input');color.type='color';color.id='dynamics-endColor';color.setAttribute('aria-label','Color at end of life');color.oninput=()=>{state.endColor=color.value;persist();};end.append(color);panel.append(end);
 const recipes=document.createElement('div');recipes.className='dynamics-recipes';for(const [label,id,changes]of [ ['Add tornado','vortex',{shape:'cone',motion:'preset',speed:30,windZ:70,vortexForce:260,attraction:80,forceZ:100,drag:.4,life:6,size:6,gravity:0}],['Add black hole','galaxy',{shape:'sphere',motion:'preset',speed:12,vortexForce:280,attraction:500,forceZ:100,drag:.6,life:6,size:3,endSize:.1,trail:true}],['Add drifting smoke','smoke',{windX:65,windZ:25,drag:.8,colorOverLife:true,endColor:'#323b50'}],['Add ricochet sparks','meteor',{bounce:true,collisionResponse:'bounce',collisionHeight:0,restitution:.85,surfaceFriction:.05,rotationSpeed:240,colorOverLife:true,endColor:'#ec3b16'}] ]){const button=document.createElement('button');button.textContent=label;button.onclick=()=>addParticleLayer({...EmberCatalog.presets.find(p=>p.id===id),...changes},label.slice(4));recipes.append(button);}panel.insertBefore(recipes,panel.children[2]);
 const reset=document.createElement('button');reset.textContent='Reset these controls';reset.onclick=()=>{Object.assign(state,EmberDynamics.defaults);sync();persist();};panel.append(reset);$('#animation-panel').before(panel);
 function refresh(){for(const key of Object.keys(EmberDynamics.ranges)){const input=$('#dynamics-'+key);input.value=state[key]??EmberDynamics.defaults[key];input.disabled=key==='rotationSpeed'?false:['collisionHeight','restitution','surfaceFriction'].includes(key)?!state.bounce||state.motion==='orbit':state.motion==='orbit';if(['restitution','surfaceFriction'].includes(key)&&state.collisionResponse==='kill')input.disabled=true;}select.value=state.collisionResponse||'bounce';select.disabled=!state.bounce||state.motion==='orbit';toggle.checked=!!state.colorOverLife;color.value=state.endColor||EmberDynamics.defaults.endColor;color.disabled=!state.colorOverLife;}
 const previous=sync;sync=()=>{previous();refresh();};const oldBounce=$('#advanced-bounce').oninput;$('#advanced-bounce').oninput=event=>{oldBounce(event);refresh();};refresh();
})();
